define("theme_learnlingo/sticky-footer",["core/pending","core/sticky-footer"],function(pendingModule,stickyFooter){"use strict";const Pending=pendingModule.default||pendingModule;const{registerManager,init:defaultInit}=stickyFooter;const SELECTORS={STICKYFOOTER:".stickyfooter",PAGE:"#page"};const CLASSES={HASSTICKYFOOTER:"hasstickyfooter"};let initialized=false;let previousScrollPosition=0;let enabled=false;const scrollSpy=()=>{if(!enabled){return}if(document.body.clientWidth>=768){return}let scrollPosition=window.scrollY;if(scrollPosition>previousScrollPosition){hideStickyFooter()}else{showStickyFooter()}previousScrollPosition=scrollPosition};const isDisabledByDefault=()=>{const footer=document.querySelector(SELECTORS.STICKYFOOTER);if(!footer){return false}return!!footer.dataset.disable};const showStickyFooter=()=>{const pendingPromise=new Pending("theme_learnlingo/sticky-footer:enabling");const footer=document.querySelector(SELECTORS.STICKYFOOTER);const page=document.querySelector(SELECTORS.PAGE);if(footer&&page){document.body.classList.add(CLASSES.HASSTICKYFOOTER);page.classList.add(CLASSES.HASSTICKYFOOTER)}setTimeout(()=>pendingPromise.resolve(),1e3)};const hideStickyFooter=()=>{document.body.classList.remove(CLASSES.HASSTICKYFOOTER);const page=document.querySelector(SELECTORS.PAGE);page?.classList.remove(CLASSES.HASSTICKYFOOTER)};const enableStickyFooter=()=>{enabled=true;showStickyFooter()};const disableStickyFooter=()=>{enabled=false;hideStickyFooter()};const init=()=>{if(initialized||document.body.classList.contains("behat-site")){defaultInit();return}initialized=true;if(!isDisabledByDefault()){enableStickyFooter()}document.addEventListener("scroll",scrollSpy);registerManager({enableStickyFooter:enableStickyFooter,disableStickyFooter:disableStickyFooter})};return{enableStickyFooter:enableStickyFooter,disableStickyFooter:disableStickyFooter,init:init}});